from collections.abc import Mapping


def installation_order(packages):
    if not isinstance(packages, Mapping):
        raise TypeError("packages must be a mapping")
    graph = {}
    for name, dependencies in packages.items():
        if not isinstance(name, str) or not name:
            raise ValueError("package names must be non-empty strings")
        if not isinstance(dependencies, (list, tuple, set)):
            raise TypeError("dependencies must be a list, tuple, or set")
        copied = set()
        for dependency in dependencies:
            if not isinstance(dependency, str) or not dependency:
                raise ValueError("dependency names must be non-empty strings")
            copied.add(dependency)
        graph[name] = copied
    unknown = {dependency for values in graph.values() for dependency in values} - set(graph)
    if unknown:
        raise ValueError("unknown dependency")

    visiting = set()
    visited = set()
    order = []

    def visit(name):
        if name in visiting:
            raise ValueError("dependency cycle")
        if name in visited:
            return
        visiting.add(name)
        for dependency in sorted(graph[name]):
            visit(dependency)
        visiting.remove(name)
        visited.add(name)
        order.append(name)

    for name in sorted(graph):
        visit(name)
    order.reverse()
    return order
```

