import copy
import unittest

from solution import installation_order


class InstallationOrderTests(unittest.TestCase):
    def test_dependencies_precede_dependents(self):
        packages = {
            "app": ["core", "ui"],
            "ui": ["core"],
            "core": [],
        }
        self.assertEqual(installation_order(packages), ["core", "ui", "app"])

    def test_alphabetical_determinism_and_duplicate_dependencies(self):
        packages = {
            "z": [],
            "app": ["lib-b", "lib-a", "lib-a"],
            "lib-b": [],
            "lib-a": [],
        }
        self.assertEqual(installation_order(packages), ["lib-a", "lib-b", "app", "z"])
        set_based = {"root": {"zdep", "adep"}, "zdep": [], "adep": []}
        self.assertEqual(installation_order(set_based), ["adep", "zdep", "root"])

    def test_empty_mapping(self):
        self.assertEqual(installation_order({}), [])

    def test_input_is_not_mutated(self):
        packages = {"a": ["b", "b"], "b": []}
        before = copy.deepcopy(packages)
        installation_order(packages)
        self.assertEqual(packages, before)

    def test_unknown_dependency_and_cycles(self):
        with self.assertRaises(ValueError):
            installation_order({"a": ["missing"]})
        with self.assertRaises(ValueError):
            installation_order({"a": ["a"]})
        with self.assertRaises(ValueError):
            installation_order({"a": ["b"], "b": ["c"], "c": ["a"]})

    def test_container_type_validation(self):
        with self.assertRaises(TypeError):
            installation_order([])
        for dependencies in ["b", {"b": True}, None]:
            with self.subTest(dependencies=dependencies):
                with self.assertRaises(TypeError):
                    installation_order({"a": dependencies})

    def test_name_validation(self):
        for packages in [{"": []}, {1: []}, {"a": [""]}, {"a": [1]}]:
            with self.subTest(packages=packages):
                with self.assertRaises(ValueError):
                    installation_order(packages)


if __name__ == "__main__":
    unittest.main()

